    "Every booking gets a simplified tax invoice with QR code, reported to ZATCA within 24 hours. Corporate and school bookings get standard B2B invoices with your VAT number, PO number and Net 30 terms, cleared before they are shared. Credit notes are issued automatically for refunds. Bilingual Arabic and English, PDF/A-3 and XML.",
