  "screen.public.forBusiness.faq.contact":
    "Still unsure? Email partners@trips-enjoy.com and our partner team replies within 1 working day.",
  "screen.public.forBusiness.faq.q1":
    "Do I need a plan to use the organization, driver or photographer app?",
  "screen.public.forBusiness.faq.a1":
    "Yes. Each of these apps needs an active plan. If a renewal fails you keep full access for 7 days while you update your card; after that the app is locked to billing, statements and support until you renew. Money you are owed is still paid out.",
  "screen.public.forBusiness.faq.q2": "How long does approval take?",
  "screen.public.forBusiness.faq.a2":
    "We review applications within 2 working days. If something is missing we tell you exactly what to fix, and you have 14 days to send it. Drivers may be asked for a lab test before their first trip.",
  "screen.public.forBusiness.faq.q3": "When do organizers get paid?",
  "screen.public.forBusiness.faq.a3":
    "Travellers pay Trips Enjoy at booking. Once the trip is completed, we pay your net amount to your IBAN every Monday at 06:00, on every plan: bookings minus refunds, 8% commission, 2.2% payment fees and driver or photographer deals.",
  "screen.public.forBusiness.faq.q4": "How do drivers and photographers get paid?",
  "screen.public.forBusiness.faq.a4":
    "When both sides finalize a deal, the agreed amount is paid by Trips Enjoy after the trip, minus 10% commission for drivers or 12% for photographers. Payouts run every Monday at 06:00, with no minimum.",
  "screen.public.forBusiness.faq.q5": "Are the invoices ZATCA compliant?",
  "screen.public.forBusiness.faq.a5":
    "Yes. Booking invoices are simplified tax invoices reported to ZATCA within 24 hours. B2B invoices for schools and companies are standard tax invoices, cleared before sharing, with QR code, UUID and your VAT number.",
  "screen.public.forBusiness.faq.q6": "Can I change or cancel my plan?",
  "screen.public.forBusiness.faq.a6":
    "Upgrades apply immediately and are prorated. Downgrades and cancellations take effect at the end of your billing period, and you keep access until then.",
